    ('Machine Learning Engineer', 'Natural Language Processing', TRUE, 3),
    ('Machine Learning Engineer', 'Docker', FALSE, 2), ('Machine Learning Engineer', 'scikit-learn', FALSE, 3),
    ('Data Analyst', 'SQL', TRUE, 3), ('Data Analyst', 'Power BI', TRUE, 3),
    ('Data Analyst', 'Python', FALSE, 2), ('Data Analyst', 'Pandas', FALSE, 2),
    ('NLP Research Intern', 'Python', TRUE, 3), ('NLP Research Intern', 'Natural Language Processing', TRUE, 2),
    ('NLP Research Intern', 'PyTorch', FALSE, 2),
    ('Frontend Developer (React / Next.js)', 'React', TRUE, 3), ('Frontend Developer (React / Next.js)', 'Next.js', TRUE, 3),
    ('Frontend Developer (React / Next.js)', 'JavaScript', TRUE, 3), ('Frontend Developer (React / Next.js)', 'Tailwind CSS', FALSE, 2),
    ('Frontend Developer (React / Next.js)', 'TypeScript', FALSE, 2),
    ('Backend Engineer (Node.js)', 'Node.js', TRUE, 4), ('Backend Engineer (Node.js)', 'Express', TRUE, 3),
    ('Backend Engineer (Node.js)', 'PostgreSQL', TRUE, 3), ('Backend Engineer (Node.js)', 'REST API Design', TRUE, 3),
    ('Backend Engineer (Node.js)', 'Docker', FALSE, 2),
    ('Full Stack Developer', 'React', TRUE, 3), ('Full Stack Developer', 'Node.js', TRUE, 3),
    ('Full Stack Developer', 'MongoDB', FALSE, 2),
    ('DevOps Engineer', 'AWS', TRUE, 3), ('DevOps Engineer', 'Kubernetes', TRUE, 3),
    ('DevOps Engineer', 'Terraform', TRUE, 3), ('DevOps Engineer', 'Docker', TRUE, 4), ('DevOps Engineer', 'CI/CD', FALSE, 3),
    ('Site Reliability Engineer', 'Linux', TRUE, 4), ('Site Reliability Engineer', 'Python', TRUE, 3),
    ('Site Reliability Engineer', 'Kubernetes', FALSE, 3)
) AS v(title, skill, required, min_prof)
