-- -------------------------------------------------------------- resumes ----
-- Text-only demo resumes (storage_path NULL). extracted_text is what will be
-- embedded in the embeddings stage.
INSERT INTO resumes (candidate_id, file_name, mime_type, extracted_text, is_primary, uploaded_at)
SELECT u.user_id, v.file_name, 'text/plain', v.body, TRUE, u.created_at + INTERVAL '1 hour'
FROM (VALUES
    ('aditi.sharma@mail.example', 'aditi_sharma_resume.txt',
     'Machine Learning Engineer with 3 years of experience building NLP systems. At a fictional e-commerce startup I trained transformer-based text classifiers in PyTorch for product categorisation, improving accuracy by 9 percent, and built a semantic search service using sentence embeddings. Deployed models as Docker containers behind a FastAPI service. Skilled in Python, scikit-learn, model evaluation and experiment tracking. M.Tech in Computer Science.'),
    ('rohan.verma@mail.example', 'rohan_verma_resume.txt',
     'Data Scientist with 5 years of experience in forecasting and deep learning. Built demand-forecasting models in TensorFlow for a fictional grocery chain, reducing stock-outs. Strong statistics background: hypothesis testing, regression, time-series analysis. Daily user of Python, Pandas and SQL. Mentored junior analysts and presented findings to business leaders. M.Sc in Statistics.'),
    ('sneha.kulkarni@mail.example', 'sneha_kulkarni_resume.txt',
     'Frontend Developer with 2 years of experience creating responsive web applications in React and JavaScript. Migrated a marketing site to Next.js and improved Lighthouse performance from 62 to 94. Comfortable with HTML, CSS, accessibility best practices and REST API integration. Enjoys working closely with designers. B.E in Information Technology.'),
    ('vikram.chauhan@mail.example', 'vikram_chauhan_resume.txt',
     'Senior Frontend Engineer with 4.5 years of experience. Led the design-system team at a fictional fintech company, building a reusable React and TypeScript component library styled with Tailwind CSS. Built server-rendered pages in Next.js, set up visual regression testing, and mentored three junior developers. B.Tech in Computer Science.'),
    ('ananya.gupta@mail.example', 'ananya_gupta_resume.txt',
     'Backend Developer with 3 years of experience designing REST APIs in Node.js and Express. Modelled relational schemas in PostgreSQL, optimised slow queries with indexes, and wrote integration tests. Containerised services with Docker and deployed them through GitHub Actions pipelines. B.Tech in Computer Science.'),
    ('karthik.subramanian@mail.example', 'karthik_subramanian_resume.txt',
     'Java Backend Engineer with 6 years of experience building Spring Boot microservices for a fictional insurance platform. Designed REST APIs, implemented event-driven processing with message queues, and tuned PostgreSQL queries. Experienced with JUnit testing, code reviews and on-call support. B.E in Electronics and Communication.'),
    ('ishita.banerjee@mail.example', 'ishita_banerjee_resume.txt',
     'Data Analyst with 2 years of experience. Wrote complex SQL queries and built Power BI dashboards tracking sales performance across 40 stores. Automated weekly reporting with Python and Pandas, saving 6 hours per week. Strong communicator who presents insights to non-technical managers. B.Sc in Economics.'),
    ('farhan.qureshi@mail.example', 'farhan_qureshi_resume.txt',
     'Junior Data Analyst with 1 year of experience. Created Tableau dashboards for customer-churn analysis and maintained Excel reporting models. Comfortable writing SQL joins and aggregations and applying basic statistics to A/B test results. BBA in Business Analytics.'),
    ('neha.bhatt@mail.example', 'neha_bhatt_resume.txt',
     'DevOps Engineer with 4 years of experience running production workloads on Kubernetes in AWS. Wrote Terraform modules for VPCs, EKS clusters and RDS, built CI/CD pipelines with GitHub Actions and Argo CD, and containerised legacy applications with Docker. Set up monitoring and alerting with Prometheus. B.Tech in Information Technology.'),
    ('siddharth.pillai@mail.example', 'siddharth_pillai_resume.txt',
     'Site Reliability Engineer with 3 years of experience. Administered Linux servers, automated deployments with Jenkins and Docker, and wrote Python scripts for log analysis. Built Grafana dashboards and participated in on-call rotations and post-incident reviews. B.Tech in Computer Science.'),
    ('divya.krishnan@mail.example', 'divya_krishnan_resume.txt',
     'Recent graduate in AI and Machine Learning. Final-year project: a sentiment analysis system for regional-language product reviews using fine-tuned transformer models in PyTorch. Completed a research internship on text summarisation. Proficient in Python, NumPy and basic NLP techniques. B.Tech in AI and Machine Learning.'),
    ('aman.malhotra@mail.example', 'aman_malhotra_resume.txt',
     'Full Stack Developer with 3 years of experience on the MERN stack. Built a booking platform with React on the frontend and Node.js, Express and MongoDB on the backend. Implemented JWT authentication, payment integration and admin dashboards. Some experience with Python scripting. Master of Computer Applications.')
) AS v(email, file_name, body)
JOIN users u ON u.email = v.email
WHERE NOT EXISTS (SELECT 1 FROM resumes r WHERE r.candidate_id = u.user_id AND r.is_primary);

